`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is asserted on cycle 0 so k-induction starts from a valid state
    always @(*) if (!f_past_valid) assume(!rst_n);

    always @(posedge clk) begin
        // P_RST_COUNT_ZERO: count_o is 0 right after reset
        if (f_past_valid && $past(!rst_n)) begin
            P_RST_COUNT_ZERO: assert(count_o == 8'd0);
        end
        // P_RST_WRAP_LOW: wrap_o is 0 right after reset
        if (f_past_valid && $past(!rst_n)) begin
            P_RST_WRAP_LOW: assert(wrap_o == 1'b0);
        end
        // P_LOAD_TAKES_EFFECT: The cycle after a load, count_o equals the loaded value
        if (f_past_valid && rst_n && ($past(load_i && rst_n))) begin
            P_LOAD_TAKES_EFFECT: assert(count_o == $past(load_val_i));
        end
        // P_WRAP_NEEDS_COUNT_STEP: wrap_o only follows an enabled, non-load step
        if (f_past_valid && rst_n && (wrap_o)) begin
            P_WRAP_NEEDS_COUNT_STEP: assert($past(en_i) && !$past(load_i));
        end
        // C_REACH_WRAP: wrap_o is reachable
        if (f_past_valid && rst_n) begin
            C_REACH_WRAP: cover(wrap_o);
        end
    end
`endif
